      {
        "start": 78.8,
        "end": 79.56,
        "text": "你肯定是行了"
      },
      {
        "start": 79.56,
        "end": 81.03999999999999,
        "text": "你肯定是能拿到一定的结果了"
      },
      {
        "start": 81.03999999999999,
